import{_ as p,a0 as n,w as l,s as d,ao as r,I as o,x as e,a1 as i,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在終端輸入密碼時顯示星號 | LCTT x X-CMD","titleTemplate":false,"description":"如何在終端輸入密碼時顯示星號 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在終端輸入密碼時顯示星號 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在終端輸入密碼時顯示星號 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20180105 How To Display Asterisks When You Type Password In terminal","title":"如何在終端輸入密碼時顯示星號","tag":"201802","desc":""},"relativePath":"201802/20180105 How To Display Asterisks When You Type Password In terminal.md","filePath":"[post].md"}'),h={name:"201802/20180105 How To Display Asterisks When You Type Password In terminal.md"};function c(u,s,g,k,m,w){const t=n("Link");return l(),d("div",null,[s[13]||(s[13]=r('<h1 id="如何在終端輸入密碼時顯示星號" tabindex="-1">如何在終端輸入密碼時顯示星號 <a class="header-anchor" href="#如何在終端輸入密碼時顯示星號" aria-label="Permalink to “如何在終端輸入密碼時顯示星號”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/01/Display-Asterisks-When-You-Type-Password-In-terminal-1-720x340.png" alt=""></p><p>當你在 Web 瀏覽器或任何 GUI 登錄中輸入密碼時，密碼會被標記成星號 <code>********</code> 或圓點符號 <code>•••••••••••••</code> 。這是內置的安全機制，以防止你附近的用户看到你的密碼。但是當你在終端輸入密碼來執行任何 <code>sudo</code> 或 <code>su</code> 的管理任務時，你不會在輸入密碼的時候看見星號或者圓點符號。它不會有任何輸入密碼的視覺指示，也不會有任何光標移動，什麼也沒有。你不知道你是否輸入了所有的字符。你只會看到一個空白的屏幕！</p><p>看看下面的截圖。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/password-1.png" alt=""></p><p>正如你在上面的圖片中看到的，我已經輸入了密碼，但沒有任何指示（星號或圓點符號）。現在，我不確定我是否輸入了所有密碼。這個安全機制也可以防止你附近的人猜測密碼長度。當然，這種行為可以改變。這是本指南要説的。這並不困難。請繼續閲讀。</p><h4 id="當你在終端輸入密碼時顯示星號" tabindex="-1">當你在終端輸入密碼時顯示星號 <a class="header-anchor" href="#當你在終端輸入密碼時顯示星號" aria-label="Permalink to “當你在終端輸入密碼時顯示星號”">​</a></h4><p>要在終端輸入密碼時顯示星號，我們需要在 <code>/etc/sudoers</code> 中做一些小修改。在做任何更改之前，最好備份這個文件。為此，只需運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cp /etc/sudoers{,.bak}</span></span></code></pre></div><p>上述命令將 <code>/etc/sudoers</code> 備份成名為 <code>/etc/sudoers.bak</code>。你可以恢復它，以防萬一在編輯文件後出錯。</p><p>接下來，使用下面的命令編輯 <code>/etc/sudoers</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo visudo</span></span></code></pre></div><p>找到下面這行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Defaults env_reset</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/visudo-1.png" alt=""></p><p>在該行的末尾添加一個額外的單詞 <code>,pwfeedback</code>，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Defaults env_reset,pwfeedback</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/visudo-1-1.png" alt=""></p><p>然後，按下 <code>CTRL + x</code> 和 <code>y</code> 保存並關閉文件。重新啓動終端以使更改生效。</p><p>現在，當你在終端輸入密碼時，你會看到星號。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/visudo-2.png" alt=""></p><p>如果你對在終端輸入密碼時看不到密碼感到不舒服，那麼這個小技巧會有幫助。請注意，當你輸入輸入密碼時其他用户就可以預測你的密碼長度。如果你不介意，請按照上述方法進行更改，以使你的密碼可見（當然，顯示為星號！）。</p><p>現在就是這樣了。還有更好的東西。敬請關注！</p><p>乾杯!</p><hr>',25)),o("p",null,[s[1]||(s[1]=e("via: ",-1)),i(t,{href:"https://www.ostechnix.com/display-asterisks-type-password-terminal/"},{default:a(()=>[...s[0]||(s[0]=[e("https://www.ostechnix.com/display-asterisks-type-password-terminal/",-1)])]),_:1})]),o("p",null,[s[5]||(s[5]=e("作者：",-1)),i(t,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...s[2]||(s[2]=[e("SK",-1)])]),_:1}),s[6]||(s[6]=e(" 譯者：",-1)),i(t,{href:"https://github.com/geekpi"},{default:a(()=>[...s[3]||(s[3]=[e("geekpi",-1)])]),_:1}),s[7]||(s[7]=e(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:a(()=>[...s[4]||(s[4]=[e("wxy",-1)])]),_:1})]),o("p",null,[s[10]||(s[10]=e("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[8]||(s[8]=[e("LCTT",-1)])]),_:1}),s[11]||(s[11]=e(" 原創編譯，",-1)),i(t,{href:"https://linux.cn/"},{default:a(()=>[...s[9]||(s[9]=[e("Linux中國",-1)])]),_:1}),s[12]||(s[12]=e(" 榮譽推出",-1))])])}const x=p(h,[["render",c]]);export{T as __pageData,x as default};
